begin transaction read only;
select version,name,cardinality(statements)=1 as one_statement,md5(replace(statements[1],E'\r\n',E'\n'))='88cdbe90a24be1fe11cd7caf445ecfe7' as source_exact_match from supabase_migrations.schema_migrations where version='20261029120000';
select 'files' as relation,count(*) from public.retail_provisional_files union all select 'rows',count(*) from public.retail_provisional_rows union all select 'proposals',count(*) from public.retail_provisional_proposals union all select 'events',count(*) from public.retail_provisional_events;
select t,r,has_table_privilege(r,'public.'||t,'SELECT') as sel,has_table_privilege(r,'public.'||t,'INSERT') as ins,has_table_privilege(r,'public.'||t,'UPDATE') as upd,has_table_privilege(r,'public.'||t,'DELETE') as del from unnest(array['retail_provisional_access','retail_provisional_files','retail_provisional_rows','retail_provisional_proposals','retail_provisional_events']) t cross join unnest(array['anon','authenticated','service_role']) r;
select p.oid::regprocedure,has_function_privilege('anon',p.oid,'EXECUTE') as anon_execute,has_function_privilege('authenticated',p.oid,'EXECUTE') as authenticated_execute,has_function_privilege('service_role',p.oid,'EXECUTE') as service_execute from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'rpc_retail_provisional_%';
rollback;
